"use strict";(globalThis.webpackChunkdoqumentation=globalThis.webpackChunkdoqumentation||[]).push([[8634],{66032(a,n,e){e.r(n),e.d(n,{assets:()=>o,contentTitle:()=>t,default:()=>p,frontMatter:()=>r,metadata:()=>g,toc:()=>l});const g=JSON.parse('{"id":"guides/qiskit-sdk-version-strategy","title":"Estratehiya sa bersyon ng Qiskit SDK","description":"Mga detalye tungkol sa estratehiya sa pag-bersyon ng Qiskit SDK, iskedyul ng release, estratehiya sa pag-upgrade, pre-releases, post-releases, at kung paano mamarkahan ng mga contributor ang mga deprecation.","source":"@site/i18n/tl/docusaurus-plugin-content-docs/current/guides/qiskit-sdk-version-strategy.mdx","sourceDirName":"guides","slug":"/guides/qiskit-sdk-version-strategy","permalink":"/guides/qiskit-sdk-version-strategy","draft":false,"unlisted":false,"editUrl":"https://github.com/JanLahmann/doQumentation/tree/main/docs/guides/qiskit-sdk-version-strategy.mdx","tags":[],"version":"current","frontMatter":{"title":"Estratehiya sa bersyon ng Qiskit SDK","description":"Mga detalye tungkol sa estratehiya sa pag-bersyon ng Qiskit SDK, iskedyul ng release, estratehiya sa pag-upgrade, pre-releases, post-releases, at kung paano mamarkahan ng mga contributor ang mga deprecation."},"sidebar":"tutorialsSidebar","previous":{"title":"Code of conduct","permalink":"/guides/code-of-conduct"},"next":{"title":"Gumawa ng provider","permalink":"/guides/create-a-provider"}}');var i=e(74848),s=e(28453);const r={title:"Estratehiya sa bersyon ng Qiskit SDK",description:"Mga detalye tungkol sa estratehiya sa pag-bersyon ng Qiskit SDK, iskedyul ng release, estratehiya sa pag-upgrade, pre-releases, post-releases, at kung paano mamarkahan ng mga contributor ang mga deprecation."},t="Estratehiya sa bersyon ng Qiskit SDK {#qiskit-sdk-version-strategy}",o={},l=[{value:"Iskedyul ng release",id:"release-schedule",level:2},{value:"Estratehiya sa pag-upgrade",id:"upgrade-strategy",level:2},{value:"Mga pre-release",id:"pre-releases",level:2},{value:"Mga post-release",id:"post-releases",level:2},{value:"Paano maaaring markahan ng mga contributor ang mga deprecation",id:"how-contributors-can-mark-deprecations",level:2}];function m(a){const n={a:"a",code:"code",h1:"h1",h2:"h2",header:"header",img:"img",p:"p",strong:"strong",...(0,s.R)(),...a.components};return(0,i.jsxs)(i.Fragment,{children:["\n",(0,i.jsx)(n.header,{children:(0,i.jsx)(n.h1,{id:"qiskit-sdk-version-strategy",children:"Estratehiya sa bersyon ng Qiskit SDK"})}),"\n",(0,i.jsxs)(n.p,{children:["Ang mga numero ng bersyon ng Qiskit ay sumusunod sa ",(0,i.jsx)(n.a,{href:"https://semver.org/",children:"Semantic Versioning"}),".\nAng numero ng bersyon ay binubuo ng tatlong pangunahing bahagi: ang major, minor, at\npatch na bersyon. Halimbawa, sa numero ng bersyon na ",(0,i.jsx)(n.code,{children:"X.Y.Z"}),", ang ",(0,i.jsx)(n.code,{children:"X"})," ay ang major na bersyon,\nang ",(0,i.jsx)(n.code,{children:"Y"})," ay ang minor na bersyon, at ang ",(0,i.jsx)(n.code,{children:"Z"})," ay ang patch na bersyon."]}),"\n",(0,i.jsxs)(n.p,{children:["Ang mga pagbabagong nakaka-apekto sa API ay nakalaan para sa mga major na release ng bersyon. Ang ",(0,i.jsx)(n.strong,{children:"pinakamaikling"}),"\npanahon sa pagitan ng mga major na release ng bersyon ay isang taon. Ang mga minor na bersyon ay nagpapakilala ng\nmga bagong feature at bug fix nang hindi nasisira ang compatibility ng API, at\npana-panahon (kasalukuyang bawat tatlong buwan) ay inilalathala para ",(0,i.jsx)(n.strong,{children:"lamang"})," sa\nkasalukuyang major na bersyon. Ang mga patch na bersyon ay nagbibigay ng mga ayos para sa mga bug na natukoy sa\npinakabagong minor na bersyon ng bawat aktibong sinusuportahang release series (iyon ay, ang\nmajor na bersyon). Sumusuporta kami ng hanggang dalawang release series sa isang pagkakataon, na nangyayari\nlamang sa panahon ng overlap kasunod ng isang bagong major na release ng bersyon,\nna inilarawan nang mas detalyado sa ibaba."]}),"\n",(0,i.jsx)(n.h2,{id:"release-schedule",children:"Iskedyul ng release"}),"\n",(0,i.jsx)(n.p,{children:"Ang isang tentative na iskedyul ng release ay kasama sa ibaba:"}),"\n",(0,i.jsx)(n.p,{children:(0,i.jsx)(n.img,{alt:"Tentative na iskedyul ng release ng Qiskit",src:e(81356).A+"",width:"1049",height:"360"})}),"\n",(0,i.jsxs)(n.p,{children:["Para sa isang napapanahong iskedyul ng release, sumangguni sa ",(0,i.jsx)(n.a,{href:"https://github.com/Qiskit/qiskit/milestones",children:"listahan ng milestones"})," ng GitHub project ng Qiskit, na palaging naglalaman ng kasalukuyang plano ng release."]}),"\n",(0,i.jsx)(n.p,{children:"Sa paglabas ng isang bagong major na bersyon, ang nakaraang major na bersyon ay sinusuportahan\nng hindi bababa sa anim na buwan na may mga bug fix lamang, at isang taon para sa mga security fix. Sa\npanahong ito, ang mga patch release lamang ang inilalathala para sa major na bersyon na ito.\nAng isang panghuling patch na bersyon ay inilalathala kapag tinanggal na ang suporta, at ang release na iyon\nay nagdodokumento rin ng katapusan ng suporta para sa major na bersyon series na iyon. Kailangan ng mas mahabang\nwindow ng suporta para sa nakaraang major na bersyon dahil nagbibigay ito sa mga downstream\nconsumer ng Qiskit at sa kanilang mga gumagamit ng pagkakataon na i-migrate ang kanilang code.\nAng mga downstream na library na\numaasa sa Qiskit ay hindi dapat agad itaas ang kanilang minimum na kinakailangang bersyon ng Qiskit sa isang bagong\nmajor na bersyon kaagad pagkatapos ng release nito dahil kailangan ng oras ng user base ng library\nupang mag-migrate sa mga bagong pagbabago sa API. Ang pagkakaroon ng extended na window ng suporta\npara sa nakaraang major na bersyon ng Qiskit ay nagbibigay sa mga downstream na proyekto ng oras upang masiguro\nang compatibility sa susunod na major na bersyon. Ang mga downstream na proyekto ay maaaring magbigay ng\nsuporta para sa dalawang release series nang sabay upang bigyan ang kanilang mga gumagamit ng landas ng migration."}),"\n",(0,i.jsxs)(n.p,{children:["Para sa mga layunin ng semantic versioning, ang pampublikong API ng Qiskit ay itinuturing na\nanumang dokumentadong module, klase, function, o method na hindi minarkahan bilang private\n(na may underscore na prefix na ",(0,i.jsx)(n.code,{children:"_"}),"). Gayunpaman, maaaring may mga tahasang pagbubukod para sa\nmga partikular na dokumentadong API. Sa ganitong mga kaso, malinaw na idodokumento ang mga API na ito\nbilang hindi pa itinuturing na mga stable na interface, at isang babala na nakikita ng gumagamit ay\naktibong ibibigay sa anumang paggamit ng mga hindi stable na interface na ito. Bukod pa rito, sa ilang\nsitwasyon, ang isang interface na minarkahan bilang private ay itinuturing na bahagi ng pampublikong\nAPI. Karaniwang nangyayari ito sa dalawang kaso lamang: alinman sa isang abstract na kahulugan ng interface\nkung saan ang mga subclass ay inilaan upang i-override/ipatupad ang isang private na method\nbilang bahagi ng pagbibigay ng implementasyon ng interface, o advanced na paggamit ng\nmga low-level na method na may mga stable na interface ngunit hindi itinuturing na ligtas na gamitin,\ndahil ang responsibilidad ay nasa gumagamit upang mapanatili ang mga class/safety invariant mismo\n(ang canonical na halimbawa nito ay ang ",(0,i.jsx)(n.code,{children:"QuantumCircuit._append"})," na method)."]}),"\n",(0,i.jsx)(n.p,{children:"Ang mga sinusuportahang bersyon ng Python, ang minimum na sinusuportahang bersyon ng Rust (para sa pagbuo ng\nQiskit mula sa source), at anumang mga dependency ng Python package (kasama ang minimum na\nsinusuportahang mga bersyon ng mga dependency) na ginagamit ng Qiskit ay hindi bahagi ng mga\ngarantiya ng backwards compatibility at maaaring magbago sa anumang release. Ang minor o major na\nrelease ng bersyon lamang ang magtatataas ng mga minimum na kinakailangan para sa paggamit o pagbuo ng Qiskit\n(kasama ang pagdaragdag ng mga bagong dependency), ngunit ang mga patch fix ay maaaring magsama ng suporta para sa\nmga bagong bersyon ng Python o iba pang mga dependency. Karaniwang ang minimum na bersyon ng isang\ndependency ay tinatataas lamang kapag ang mga lumang bersyon ng dependency ay nag-expire na sa suporta o\nkapag hindi posible na mapanatili ang compatibility sa pinakabagong release ng\ndependency at ang mas lumang bersyon."}),"\n",(0,i.jsx)(n.h2,{id:"upgrade-strategy",children:"Estratehiya sa pag-upgrade"}),"\n",(0,i.jsxs)(n.p,{children:["Kapag may bagong major na bersyon na inilabas, ang inirerekomendang landas ng upgrade\nay ang una ay mag-upgrade sa pinakabagong minor na bersyon sa nakaraang major na\nbersyon. Kaunti bago ang isang bagong major na bersyon, isang panghuling minor na bersyon ang\nilalathala. Ang panghuling minor na release ng bersyon na ito na ",(0,i.jsx)(n.code,{children:"X.Y+1.0.0"})," ay katumbas ng\n",(0,i.jsx)(n.code,{children:"X.Y.0"})," ngunit may mga babala at deprecation para sa anumang pagbabago sa API na\nginawa sa bagong major na bersyon series."]}),"\n",(0,i.jsx)(n.p,{children:"Halimbawa, kaagad bago ang 1.0.0 release, isang 0.46.0 release ang\nilalathala. Ang 0.46.0 release ay katumbas ng 0.45.0 release ngunit may\nkaragdagang mga babala ng deprecation na nagdodokumento ng mga pagbabago sa API na ginawa bilang\nbahagi ng 1.0.0 release. Ang pattern na ito ay gagamitin para sa anumang mga release ng major na\nbersyon sa hinaharap."}),"\n",(0,i.jsxs)(n.p,{children:["Ang mga gumagamit ng Qiskit ay dapat munang mag-upgrade sa panghuling minor na\nbersyon na ito upang makita ang anumang mga babala ng deprecation at ayusin ang kanilang\npaggamit ng Qiskit bago subukan ang isang posibleng breaking release. Ang nakaraang\nmajor na bersyon ay susuportahan ng hindi bababa sa anim na buwan upang magbigay ng sapat na oras\npara mag-upgrade. Ang isang tipikal na pattern upang pamahalaan ito ay i-pin ang maximum na bersyon upang\nmaiwasan ang paggamit ng susunod na major na release series hanggang sigurado ka sa compatibility.\nHalimbawa, ang pagtukoy ng ",(0,i.jsx)(n.code,{children:"qiskit<2"})," sa isang requirements file kapag ang kasalukuyang\nmajor na bersyon ng Qiskit ay 1 ay tinitiyak na gumagamit ka ng isang bersyon ng Qiskit\nna walang mga breaking na pagbabago sa API."]}),"\n",(0,i.jsxs)(n.p,{children:["Ang pag-cap ng bersyon na mas mababa sa susunod na major na bersyon\nay tinitiyak na makikita mo ang anumang mga babala ng deprecation bago ang isang\nmajor na release ng bersyon.\nKung wala ang cap, ang ",(0,i.jsx)(n.code,{children:"pip"})," ay nag-iinstall\nng pinakabagong bersyon na available bilang default."]}),"\n",(0,i.jsxs)(n.p,{children:["Ang QPY serialization format ay backwards-compatible upang ang isang bagong Qiskit release ay palaging makaload ng isang QPY\nfile na na-generate gamit ang isang mas lumang release ng Qiskit. Gayunpaman, ang format ay hindi forward-compatible kaya, sa prinsipyo, hindi posible\nna mag-load ng mga QPY file na na-generate gamit ang isang mas bagong bersyon ng Qiskit gamit ang isang mas lumang release. Upang mapadali ang migration ng gumagamit sa mga major na release ng bersyon, ang ",(0,i.jsx)(n.a,{href:"https://docs.quantum.ibm.com/api/qiskit/qpy#dump",children:(0,i.jsx)(n.code,{children:"qiskit.qpy.dump()"})})," function ay palaging susuporta ng hindi bababa sa isang overlapping na bersyon sa pagitan ng ",(0,i.jsx)(n.code,{children:"X.0.0"})," at ng ",(0,i.jsx)(n.code,{children:"X-1.Y.0"})," release (kung saan ang ",(0,i.jsx)(n.code,{children:"Y"})," ay ang huling minor na bersyon ng\nseries na iyon). Ang parameter na ",(0,i.jsx)(n.code,{children:"qiskit.qpy.dump(..., version=...)"})," ay magbibigay-daan sa pag-save ng mga QPY format file na maaaring i-load ng parehong major na bersyon mula sa mas bagong\nrelease. Tingnan ang karagdagang detalye sa ",(0,i.jsx)(n.a,{href:"https://github.com/Qiskit/RFCs/blob/master/0020-release_cycle.md#qpy-support",children:"RFC 0020"}),"."]}),"\n",(0,i.jsx)(n.h2,{id:"pre-releases",children:"Mga pre-release"}),"\n",(0,i.jsxs)(n.p,{children:["Para sa bawat minor at major na release ng bersyon, naglalathala ang Qiskit ng mga pre-release na\ncompatible sa ",(0,i.jsx)(n.a,{href:"https://peps.python.org/pep-0440/",children:"PEP440"}),". Karaniwang\nang mga ito ay mga release candidate ng form na ",(0,i.jsx)(n.code,{children:"X.Y.0rc1"}),". Ang mga ",(0,i.jsx)(n.code,{children:"rc"})," release\nay magkakaroon ng finalized na API surface at ginagamit upang subukan ang isang prospective na release."]}),"\n",(0,i.jsxs)(n.p,{children:["Tandaan na kapag ang isa sa mga PEP440 pre-release suffix (tulad ng ",(0,i.jsx)(n.code,{children:"a"}),", ",(0,i.jsx)(n.code,{children:"b"}),", o ",(0,i.jsx)(n.code,{children:"pre"}),") ay\ninilathala, wala itong parehong mga garantiya ng isang ",(0,i.jsx)(n.code,{children:"rc"})," release, at\npreview release lamang ito. Ang API ay maaaring magbago sa pagitan ng mga pre-release na ito\nat ng panghuling release na may numero ng bersyon na iyon. Halimbawa, ang ",(0,i.jsx)(n.code,{children:"1.0.0pre1"})," ay maaaring may\nibang panghuling API kaysa sa ",(0,i.jsx)(n.code,{children:"1.0.0"}),"."]}),"\n",(0,i.jsx)(n.h2,{id:"post-releases",children:"Mga post-release"}),"\n",(0,i.jsxs)(n.p,{children:["Kung may mga isyu sa packaging ng isang release, isang post-release ay maaaring\nilabas upang ayusin ito. Ang mga ito ay sumusunod sa form na ",(0,i.jsx)(n.code,{children:"X.Y.Z.1"})," kung saan ang ikaapat na\ninteger ay nagpapahiwatig na ito ang unang post-release ng ",(0,i.jsx)(n.code,{children:"X.Y.Z"})," release.\nHalimbawa, ang qiskit-terra (ang legacy na pangalan ng package para sa Qiskit) 0.25.2\nrelease ay may ilang isyu sa pag-publish ng sdist package, at isang post-release na\n0.25.2.1 ay inilathala na nag-ayos ng isyung ito. Magkapareho ang code, at\nang 0.25.2.1 ay nag-ayos lamang ng isyu sa packaging para sa release."]}),"\n",(0,i.jsx)(n.h2,{id:"how-contributors-can-mark-deprecations",children:"Paano maaaring markahan ng mga contributor ang mga deprecation"}),"\n",(0,i.jsxs)(n.p,{children:["Sumangguni sa ",(0,i.jsx)(n.a,{href:"https://github.com/Qiskit/qiskit/blob/main/DEPRECATION.md",children:"deprecation guide"})," sa repository ng Qiskit SDK para sa mga instruksyon kung paano magdagdag ng mga deprecation sa source code."]})]})}function p(a={}){const{wrapper:n}={...(0,s.R)(),...a.components};return n?(0,i.jsx)(n,{...a,children:(0,i.jsx)(m,{...a})}):m(a)}},81356(a,n,e){e.d(n,{A:()=>g});const g="data:image/avif;base64,"},28453(a,n,e){e.d(n,{R:()=>r,x:()=>t});var g=e(96540);const i={},s=g.createContext(i);function r(a){const n=g.useContext(s);return g.useMemo(function(){return"function"==typeof a?a(n):{...n,...a}},[n,a])}function t(a){let n;return n=a.disableParentContext?"function"==typeof a.components?a.components(i):a.components||i:r(a.components),g.createElement(s.Provider,{value:n},a.children)}}}]);